    ],
    "decisions": [
      "Use jose (not jsonwebtoken) for JWT verification",
      "Use Date.now() (not new Date()) for expiry timestamp comparison",
      "Use <= (not <) when comparing token expiry to current time, to fix the off-by-one bug"
    ],
    "rejected_paths": [
      "< operator for expiry comparison — off-by-one, rejects tokens valid in their final second",
      "new Date() for the current-time check — unnecessary allocation vs Date.now()",
      "jsonwebtoken library — superseded by jose for this fix"
    ],
